            "heading": "omniroute-codebase-documentation",
            "content": "> **Version:** v3.8.0\r\n> &#x2A;*Last updated:** 2026-06-28\r\n> &#x2A;*Audience:** Engineers contributing to OmniRoute or building integrations on top of it.\n>\n> For high-level architecture diagrams and the reasoning behind each subsystem, read\r\n> ARCHITECTURE.md. For deep dives on individual subsystems\r\n> (Auto Combo, MCP server, A2A server, Skills, Memory, Cloud Agents, Resilience,\r\n> Compression, etc.) see their dedicated files in this `docs/` directory."
